 @Test void inventoryPermissionSigningAuditRollbackReplayAndExpiryGate(){
  releaseIncoming(()->{});as(qa);var current=wms.get("MaterialLot",lot);var command=body("versionNo",current.path("versionNo").asLong(),"reason","Atomic freeze","signature",java.util.Map.of("reauthToken","token"));String freezeKey=key();
  permissions.remove("qa:material-inventory:freeze");as(qa);rejected(com.hospital.mes.common.exception.PermissionException.class,()->inventory.decide(lot,true,command,token(current),freezeKey));permissions.add("qa:material-inventory:freeze");as(qa);
  permissions.remove("ebr:sign");as(qa);rejected(com.hospital.mes.common.exception.PermissionException.class,()->inventory.decide(lot,true,command,token(current),freezeKey));permissions.add("ebr:sign");as(qa);
  long signatures=jdbc.queryForObject("SELECT COUNT(*) FROM gxp_signature",Long.class);
  org.mockito.Mockito.doAnswer(inv->{var a=(com.hospital.mes.audit.domain.AuditCommand)inv.getArgument(0);if(a.action().equals("INVENTORY_FREEZE"))throw new IllegalStateException("injected inventory audit failure");return inv.callRealMethod();}).when(audit).append(org.mockito.ArgumentMatchers.any());
  rejected(IllegalStateException.class,()->inventory.decide(lot,true,command,token(current),freezeKey));org.mockito.Mockito.reset(audit);
  assertThat(wms.get("MaterialLot",lot).path("inventoryStatus").asText()).isEqualTo("AVAILABLE");assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM wms_material_lot_inventory_decision WHERE material_lot_id=?",Long.class,lot)).isZero();assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM gxp_signature",Long.class)).isEqualTo(signatures);assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM platform_idempotency_record WHERE idempotency_key=?",Long.class,freezeKey)).isZero();
  var frozen=inventory.decide(lot,true,command,token(current),freezeKey);assertThat(inventory.decide(lot,true,command,token(current),freezeKey)).isEqualTo(frozen);
  rejected(com.hospital.mes.common.exception.ResourceConflictException.class,()->inventory.decide(lot,true,command.deepCopy().put("reason","Different command"),token(current),freezeKey));
  jdbc.update("UPDATE md_material_lot SET expiry_date=? WHERE id=?",java.time.LocalDate.now(java.time.ZoneOffset.UTC),lot);
  blockedCode("UNFREEZE_GATE_FAILED",()->inventory.decide(lot,false,body("versionNo",frozen.path("versionNo").asLong(),"reason","Expired cannot unfreeze","signature",java.util.Map.of("reauthToken","token")),token(frozen),key()));assertThat(inventory.history(1,Long.parseLong(lot))).hasSize(1);
 }
 JsonNode clearanceRecord(JsonNode op,String outcome,String previous,String usage){
  var b=body("versionNo",op.path("versionNo").asLong(),"outcome",outcome,"reason","Actual controlled clearance","signature",java.util.Map.of("reauthToken","token"));if(previous!=null)b.put("previousRecordId",previous);if(usage!=null)b.put("equipmentUsageId",usage);return clearances.record(id(op),b,token(op),key());
 }
 JsonNode clearanceReview(JsonNode op,String record,String decision){as(reviewer);var n=clearances.review(id(op),body("versionNo",op.path("versionNo").asLong(),"clearanceRecordId",record,"decision",decision,"reason","Independent exact clearance review","signature",java.util.Map.of("reauthToken","token")),token(op),key());as(author);return n;}
 @Test void newlyBoundEquipmentAndNewFailureInvalidateEarlierClearanceBeforeStartAndResume(){
  withClearance=true;var batch=startActualBatch(releasedBatch(false));String eid=batch.path("executionUnits").get(0).path("id").asText();var op=executionService.operations(eid).getFirst();var record=clearanceRecord(op,"PASS",null,null);var approved=clearanceReview(record,id(record.path("clearanceRecords").get(0)),"APPROVED");
  var eq=equipment.create(new com.hospital.mes.equipment.application.EquipmentCommands.Create("CLR"+suffix,"Clearance equipment","PRODUCTION_IT_SCALE",java.time.LocalDate.now(java.time.ZoneOffset.UTC).plusDays(30),"Production"),key());executionService.bindEquipment(id(op),body("equipmentId",id(eq),"usageRole","PROCESS","reason","New binding needs own clearance"),token(approved),key());var bound=executionService.operation(1,Long.parseLong(id(op)));String usage=jdbc.queryForObject("SELECT CAST(id AS CHAR) FROM mes_equipment_usage WHERE operation_execution_id=?",String.class,id(op));
  blockedCode("PRECONDITION_FAILED",()->executionService.start(id(op),body("reason","Old no-equipment clearance cannot cover new binding"),token(bound),key()));
  var fresh=clearanceRecord(bound,"PASS",null,usage);String passId=id(fresh.path("clearanceRecords").get(1));var pass=clearanceReview(fresh,passId,"APPROVED");var running=executionService.start(id(op),body("reason","All current bindings approved"),token(pass),key());var paused=executionService.pause(id(op),body("reason","Pause for new clearance"),token(running),key());var fail=clearanceRecord(paused,"FAIL",passId,usage);String failId=id(fail.path("clearanceRecords").get(2));
  as(reviewer);blockedCode("CLEARANCE_FAILED",()->clearances.review(id(op),body("versionNo",fail.path("versionNo").asLong(),"clearanceRecordId",failId,"decision","APPROVED","reason","FAIL cannot be approved","signature",java.util.Map.of("reauthToken","token")),token(fail),key()));as(author);
  blockedCode("PRECONDITION_FAILED",()->executionService.resume(id(op),body("reason","Old PASS cannot override latest FAIL"),token(fail),key()));
  var corrected=clearanceRecord(fail,"PASS",failId,usage);var reviewed=clearanceReview(corrected,id(corrected.path("clearanceRecords").get(3)),"APPROVED");assertThat(executionService.resume(id(op),body("reason","Latest clearance independently approved"),token(reviewed),key()).path("status").asText()).isEqualTo("IN_PROGRESS");assertThat(clearances.history(1,Long.parseLong(id(op)))).hasSize(4);
 }
