 @Test void requiredClearanceNeedsRealIndependentSignedEvidenceBeforeStart() {
  withClearance=true;var batch=startActualBatch(releasedBatch(false));String eid=batch.path("executionUnits").get(0).path("id").asText();var op=executionService.operations(eid).getFirst();
  blockedCode("PRECONDITION_FAILED",()->executionService.start(id(op),body("reason","No clearance evidence"),token(op),key()));
  var recorded=clearances.record(id(op),body("versionNo",op.path("versionNo").asLong(),"outcome","PASS","reason","Actual clearance execution","signature",java.util.Map.of("reauthToken","token")),token(op),key());String clearanceId=recorded.path("clearanceRecords").get(0).path("id").asText();
  var review=body("versionNo",recorded.path("versionNo").asLong(),"clearanceRecordId",clearanceId,"decision","APPROVED","reason","Independent clearance review","signature",java.util.Map.of("reauthToken","token"));
  blockedCode("INDEPENDENT_REVIEW_REQUIRED",()->clearances.review(id(op),review,token(recorded),key()));
  as(reviewer);var approved=clearances.review(id(op),review,token(recorded),key());as(author);
  var started=executionService.start(id(op),body("reason","Start after real clearance"),token(approved),key());assertThat(started.path("status").asText()).isEqualTo("IN_PROGRESS");
  for(var fact:started.path("clearanceRecords")){assertThat(verifier.verify(1,fact.path("signatureId").asLong())).isTrue();assertThat(verifier.verify(1,fact.path("review").path("signatureId").asLong())).isTrue();}
 }
 @Test void pendingIpcBlocksCompletionThenOriginalFailRequiresSignedInvalidationAndNewResult() {
  ipcDefinitions=java.util.List.of(new com.hospital.mes.process.domain.ProcessCommands.IpcDefinition("PH","Acidity",true,"NUMERIC","1","3",null,null,"SOP-IPC/V1"));
  var batch=startActualBatch(releasedBatch(false));String eid=batch.path("executionUnits").get(0).path("id").asText();var op=executionService.operations(eid).getFirst();var started=executionService.start(id(op),body("reason","Actual production start"),token(op),key());recordAndSubmitOperationForm(eid);
  var instances=executionService.operations(eid).getFirst().path("ipcInstances");assertThat(instances).hasSize(1);var instance=instances.get(0);assertThat(instance.path("status").asText()).isEqualTo("PENDING");
  blockedCode("IPC_REQUIRED_PENDING",()->executionService.complete(id(op),body("reason","Required actual IPC pending"),token(started),key()));
  var fail=ipc.submit(id(instance),body("versionNo",0,"resultNumeric","4","reason","Original measured FAIL","signature",java.util.Map.of("reauthToken","token")),token(instance),key());var original=fail.path("results").get(0);assertThat(original.path("resultConclusion").asText()).isEqualTo("FAIL");
  blockedCode("IPC_ORIGINAL_RESULT_PROTECTED",()->ipc.submit(id(instance),body("versionNo",fail.path("versionNo").asLong(),"previousRevisionId",id(original),"resultNumeric","2","reason","Cannot replace FAIL","signature",java.util.Map.of("reauthToken","token")),token(fail),key()));
  as(reviewer);var invalid=ipc.reviewResult(id(instance),body("versionNo",fail.path("versionNo").asLong(),"resultRevisionId",id(original),"disposition","INVALIDATED","reason","Approved invalid measurement; original retained","signature",java.util.Map.of("reauthToken","token")),token(fail),key());as(author);
  var pass=ipc.submit(id(instance),body("versionNo",invalid.path("versionNo").asLong(),"previousRevisionId",id(original),"resultNumeric","2","reason","New measurement after approved invalidation","signature",java.util.Map.of("reauthToken","token")),token(invalid),key());var current=pass.path("results").get(1);
  blockedCode("IPC_REQUIRED_PENDING",()->executionService.complete(id(op),body("reason","PASS still awaiting independent confirmation"),token(started),key()));as(reviewer);
  var confirmed=ipc.reviewResult(id(instance),body("versionNo",pass.path("versionNo").asLong(),"resultRevisionId",id(current),"disposition","CONFIRMED","reason","Confirm exact current PASS","signature",java.util.Map.of("reauthToken","token")),token(pass),key());as(author);
  assertThat(confirmed.path("results").get(0).path("resultConclusion").asText()).isEqualTo("FAIL");assertThat(verifier.verify(1,original.path("signatureId").asLong())).isTrue();
  var completed=executionService.complete(id(op),body("reason","All required IPC independently confirmed"),token(started),key());assertThat(completed.path("status").asText()).isEqualTo("COMPLETED");
  blockedCode("IPC_OPERATION_NOT_MUTABLE",()->ipc.reviewResult(id(instance),body("versionNo",confirmed.path("versionNo").asLong(),"resultRevisionId",id(current),"disposition","INVALIDATED","reason","Completed evidence cannot be changed","signature",java.util.Map.of("reauthToken","token")),token(confirmed),key()));
 }
 @Test void signedInventoryFreezeBlocksActualReservationAndUnfreezeRestoresEligibility() throws Exception {
  releaseIncoming(()->{}); as(qa); var batch=releasedBatch(false); as(qa);
  assertThat(application.containsBean("inventoryDecisionService")).as("approved freeze business producer exists").isTrue();
  var commands=application.getBean("inventoryDecisionService");
  var action=commands.getClass().getMethod("decide",String.class,boolean.class,JsonNode.class,String.class,String.class);
  var current=wms.get("MaterialLot",lot);
  JsonNode frozen=(JsonNode)action.invoke(commands,lot,true,body("versionNo",current.path("versionNo").asLong(),"reason","Actual signed inventory restriction","signature",java.util.Map.of("reauthToken","token")),token(current),key());
  assertThat(frozen.path("inventoryStatus").asText()).isEqualTo("FROZEN");
  assertThat(frozen.path("qualityStatus").asText()).isEqualTo("RELEASED");
  as(author); var formula=productionQuery.batch(1,Long.parseLong(id(batch))).snapshot().path("process").path("formula").path("items").get(0).path("formulaItemId").asText();
  assertReservationBlocked(id(batch),formula,token(batch)); as(qa);
  JsonNode available=(JsonNode)action.invoke(commands,lot,false,body("versionNo",frozen.path("versionNo").asLong(),"reason","Restriction resolved; QA release remains valid","signature",java.util.Map.of("reauthToken","token")),token(frozen),key());
  assertThat(available.path("inventoryStatus").asText()).isEqualTo("AVAILABLE");
  assertThat(available.path("inventoryDecisions")).hasSize(2);
  for(var decision:available.path("inventoryDecisions")) assertThat(verifier.verify(1,decision.path("signatureId").asLong())).isTrue();
  assertThat(queries.evaluate(1,Long.parseLong(lot),"PRODUCTION",java.time.Instant.now()).path("eligible").asBoolean()).isTrue();
 }
